#!/bin/bash
# Cursor sessionStart hook — generated by scripts/gen-harness-cursor.ts, do not edit.
# Answers with the dinopowers wrapper routing table (scripts/main-session-routing.txt)
# as additional_context. Subagents get no table: Cursor's subagentStart cannot inject context.

cat > /dev/null
ROOT="${CURSOR_PLUGIN_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
CONTEXT=$(cat "$ROOT/scripts/main-session-routing.txt" 2>/dev/null)
if [ -z "$CONTEXT" ]; then
  echo '{}'
  exit 0
fi
jq -n --arg context "$CONTEXT" '{ additional_context: $context }'
exit 0
